/// `ts.uri.flush`.
fn ts_uri_flush(ctx: &mut dyn p::PlanContext, _entry: u32) -> Result<Value, p::PlanExit> {
    ctx.adopt(0, 0)?;
    ctx.begin()?;
    {
        let cursor_scope = ctx.scope();
        let mut outcome = (|ctx: &mut dyn p::PlanContext| -> Result<Departure, p::PlanExit> {
            ctx.begin()?;
            ctx.local(0, 0)?;
            ctx.call(0, 0, 1)?;
            ctx.call(1, 0, 1)?;
            return Ok(Departure::Return(ctx.take(0)));
        })(ctx);
        outcome = match outcome {
            Ok(Departure::Return(value)) => Ok(Departure::Return(ctx.retain(value, 1)?)),
            Err(p::PlanExit::Raise(value)) => Err(p::PlanExit::Raise(ctx.retain(value, 1)?)),
            other => other,
        };
        ctx.unwind(cursor_scope);
        if matches!(outcome, Err(p::PlanExit::Raise(_))) {
            if let Err(p::PlanExit::Raise(value)) = outcome {
                ctx.retain(value, 2)?;
            }
            outcome = {
                let cursor_scope = ctx.scope();
                let mut outcome = (|ctx: &mut dyn p::PlanContext| -> Result<Departure, p::PlanExit> {
                    ctx.begin()?;
                    ctx.literal(0, 0)?;
                    ctx.literal(1, 1)?;
                    ctx.literal(2, 2)?;
                    ctx.call(2, 0, 3)?;
                    return Err(p::PlanExit::Raise(ctx.take(0)));
                })(ctx);
                outcome = match outcome {
                    Ok(Departure::Return(value)) => Ok(Departure::Return(ctx.retain(value, 1)?)),
                    Err(p::PlanExit::Raise(value)) => Err(p::PlanExit::Raise(ctx.retain(value, 1)?)),
                    other => other,
                };
                ctx.unbind(2);
                ctx.unwind(cursor_scope);
                outcome
            };
        }
        ctx.unbind(1);
        match outcome {
            Ok(Departure::Next) => {},
            Err(exit) => return Err(exit),
            Ok(Departure::Return(value)) => return Ok(value),
            Ok(Departure::Break) => {
                unreachable!("a loop departure needs a loop");
            },
            Ok(Departure::Continue) => {
                unreachable!("a loop departure needs a loop");
            },
        }
    }
    ctx.begin()?;
    Ok(Value::Null)
}
fn ts_uri_flush_heap(heap: &mut dyn p::TemplateHeap, args: &[Value], natives: &[lash_kernel_doc::PreparedNative]) -> Option<Value> {
    let _ = (&heap, natives);
    match args {
        [Value::List(_)] => {
            if let Some(value) = (|| {
                let v0 = heap.call(0, &[args[0]])?; let _ = v0;
                let v1 = heap.call(1, &[v0])?; let _ = v1;
                Some(v1)
            })() { return Some(value); }
            None
        },
        _ => None,
    }
}

