                let v2 = heap.index(args[0], args[1])?; let _ = v2;
                heap.bind(v2, Some(Value::Absent))?;
                let v3 = match (natives[1].entry)(&[v2, Value::Absent]) { Some(value) => value, None => heap.call(0, &[v2, Value::Absent])? }; let _ = v3;
